import app from 'flarum/admin/app';
import ExtensionPage from 'flarum/admin/components/ExtensionPage';
import MainLandingPinnedDiscussions from './components/MainLandingPinnedDiscussions';
import MaintenanceBannerSettings from './components/MaintenanceBannerSettings';
import QuickRailSettings from './components/QuickRailSettings';
app.initializers.add('flatrate-forum-navigation-admin', () => {
  (app.registry || app.extensionData).for('flatrate-forum-navigation').registerPage(class ForumNavigationAdminPage extends ExtensionPage {
    content() {
      return m("div", {
        className: "FlatRateForumNavigationAdmin container"
      }, m("div", {
        className: "Form-group"
      }, m("h2", null, "MAIN Landing"), m("p", {
        className: "helpText"
      }, "Curate Public and Member MAIN pinned discussions. These lists are independent of native Flarum Sticky and do not mutate is_sticky."), m(MainLandingPinnedDiscussions, null)), m(MaintenanceBannerSettings, null), m(QuickRailSettings, null));
    }
  });
});